"""Original applied-knowledge scenarios; references supply learning context.

No external exams are copied. Authored difficulty is a curriculum label, not an
empirically calibrated ability estimate. All numerical cases state their rules.
"""

def scenarios(text):
    result = []
    for line in text.strip().splitlines():
        prompt, answer, distractors, explanation = [value.strip() for value in line.split(" ~ ")]
        assert len(distractors.split("|")) == 3
        result.append((prompt, answer, distractors, explanation, 3))
    assert len(result) == 10
    return result


